comprobar:
ID=$(cat at-id.txt 2>/dev/null | tr -d '[:space:]')
en_cola() { atq | awk -v id="$ID" '$1 == id && $NF == "alumno" { f = 1 } END { exit !f }'; }
guarda_recordatorio() { at -c "$ID" | grep -q 'recordatorio.txt'; }
solo_uno() { [ "$(atq | awk '$NF == "alumno"' | wc -l)" -eq 1 ]; }
atq_guardado() { [ "$(wc -l < atq.txt)" -eq 1 ] && awk -v id="$ID" '$1 == id && $NF == "alumno" { f = 1 } END { exit !f }' atq.txt; }
cron_ok() { crontab -l -u alumno 2>/dev/null | grep -Eq '^0[[:space:]]+4[[:space:]]+\*[[:space:]]+\*[[:space:]]+0[[:space:]]+/home/alumno/retos/r102-cron-at/limpia\.sh[[:space:]]*$'; }
comprueba "at-id.txt contiene solo el número de un trabajo" grep -Eqx '[0-9]+' at-id.txt
comprueba "el trabajo de at-id.txt es de alumno y sigue en la cola" en_cola
comprueba "ese trabajo ejecutará un comando que escribe recordatorio.txt" guarda_recordatorio
comprueba "solo queda un trabajo de alumno en la cola (el otro está cancelado)" solo_uno
comprueba "atq.txt tiene una sola línea: el trabajo de alumno del paso 1" atq_guardado
comprueba "el crontab de alumno ejecuta limpia.sh los domingos a las 04:00" cron_ok

export GNUPGHOME=/home/alumno/retos/r102-gpg-simetrico/gnupg
C=$(mktemp -d); trap 'gpgconf --homedir "$C/gh" --kill gpg-agent 2>/dev/null; rm -rf "$C"' EXIT
mkdir -m 700 "$C/gh"; tar --exclude='S.*' -C "$GNUPGHOME" -cf - . | tar -C "$C/gh" -xf -
export GNUPGHOME="$C/gh"   # se trabaja con una copia: comprobar no escribe en el llavero del alumno
simetrico() { gpg --list-packets secreto.txt.gpg 2>/dev/null | grep -q 'symkey enc packet'; }
descifra_secreto() { gpg --batch --pinentry-mode loopback --passphrase clave-reto -d secreto.txt.gpg 2>/dev/null | grep -qx 'El codigo del almacen es 4471.'; }
clave_ed25519() { gpg --with-colons --list-secret-keys alumno@lpi.example 2>/dev/null | awk -F: '$1 == "sec" && $4 == 22 && $7 == "" { s = 1 } $1 == "uid" && $10 ~ /alumno@lpi\.example/ { u = 1 } END { exit !(s && u) }'; }
publica_ok() { grep -q 'BEGIN PGP PUBLIC KEY BLOCK' publica.asc && gpg --with-colons --show-keys publica.asc 2>/dev/null | grep -q 'alumno@lpi.example'; }
cifrado_destinatario() { gpg --list-packets mensaje.txt.gpg 2>/dev/null | grep -q 'pubkey enc packet' && ! gpg --list-packets mensaje.txt.gpg 2>/dev/null | grep -q 'symkey enc packet'; }
ida_y_vuelta() { gpg --batch -d mensaje.txt.gpg 2>/dev/null | cmp -s - mensaje.txt && cmp -s mensaje.txt mensaje-recuperado.txt; }
comprueba "secreto.txt.gpg está cifrado con contraseña (symkey)" simetrico
comprueba "secreto.txt.gpg se descifra con clave-reto y da el texto original" descifra_secreto
comprueba "existe la clave ed25519 de Alumno LPI, sin caducidad" clave_ed25519
comprueba "publica.asc es la clave pública en ASCII de alumno@lpi.example" publica_ok
comprueba "mensaje.txt.gpg va cifrado para la clave pública del destinatario" cifrado_destinatario
comprueba "mensaje-recuperado.txt es el mensaje original, descifrado" ida_y_vuelta
